/*
 * network_$wait_response - wait for the reply to request `pkt_id`
 *
 * Original address: 0x00E0F746 (module-local; the SAU2 map has no symbol
 * here; was Ghidra network_$wait_response)
 * Size: 294 bytes (0x00E0F746 .. 0x00E0F86B)
 * Generated by: Claude Opus 5.5
 *
 * Returns a Domain boolean: 0xFF when the reply arrived, 0 when the clock
 * passed TIME_$CLOCKH + timeout first.  Callers: network_$do_request
 * (0x00E0F93A), NETWORK_$READ_AHEAD (0x00E0FE16).
 *
 * Frame (link.w A6,-0x4c): (0x8) sock (D4w), (0xa) pkt_id (D3w), (0xc)
 * timeout word, (0xe) event_count (A3), (0x12) resp_buf, (0x16) resp_len
 * (D6), (0x1a) data_bufs (A2, four longwords), (0x1e) data_len (D7);
 * (-0x3c) status, (-0x38) deadline, (-0x34) the header page cell,
 * (-0x30) the APP_$RECEIVE record (reply +0x00, data +0x04, pages +0x08).
 *
 * Blocks:
 *   0x00E0F76A-0x00E0F77A  result = true; data_bufs[0] = 0; deadline =
 *                          timeout (zero-extended) + TIME_$CLOCKH
 *   0x00E0F794-0x00E0F7C4  EC_$WAIT({socket ec, TIME_$CLOCKH ec, nil},
 *                          {*event_count, deadline, 0}); not the socket ->
 *                          result = false, return
 *   0x00E0F7C8-0x00E0F7E4  (*event_count)++; APP_$RECEIVE(sock, &rec, &st);
 *                          failed -> wait again
 *   0x00E0F7E6-0x00E0F812  *data_len = reply.data_len; *resp_len =
 *                          min(0xB8, reply.template_len) (unsigned);
 *                          OS_$DATA_COPY(rec.data, resp_buf, that length)
 *   0x00E0F81C-0x00E0F832  NETBUF_$RTN_HDR(&(rec.data & ~0x3FF))
 *   0x00E0F834-0x00E0F840  data_bufs[0..3] = rec.data_pages[0..3]
 *   0x00E0F842-0x00E0F85C  reply.request_id == pkt_id -> return; else dump
 *                          any data pages (PKT_$DUMP_DATA, word result slot),
 *                          data_bufs[0] = 0, wait again
 */

#include "network/network_internal.h"
#include "os/os.h"
#include "netbuf/netbuf.h"
#include "time/time.h"

int8_t network_$wait_response(int16_t sock_num, int16_t pkt_id,
                              uint16_t timeout, int32_t *event_count,
                              int16_t *resp_buf, int16_t *resp_len_out,
                              uint32_t *data_bufs, uint16_t *data_len_out)
{
    int8_t result;                  /* D2b */
    int32_t deadline;               /* (-0x38,A6) */
    status_$t status;               /* (-0x3c,A6) */
    app_$receive_rec_t rec;         /* (-0x30,A6) */
    uint32_t hdr;                   /* (-0x34,A6) */
    const app_$reply_hdr_t *reply;  /* A0 */
    uint16_t len;                   /* D1w */
    int16_t reply_id;               /* D5w */
    int i;

    /* 0x00E0F76A-0x00E0F77A */
    result = (int8_t)0xFF;
    data_bufs[0] = 0;
    deadline = (int32_t)((uint32_t)timeout + TIME_$CLOCKH);

    for (;;) {
        /* 0x00E0F794-0x00E0F7C4 */
        if (EC_$WAIT((ec_$wait_ecs_t){{ &SOCK_$DATA.socket_ptr[sock_num]->ec,
                                        (ec_$eventcount_t *)&TIME_$CLOCKH,
                                        NULL }},
                     (ec_$wait_vals_t){{ *event_count, deadline, 0 }}) != 0) {
            result = 0;
            return result;
        }

        /* 0x00E0F7C8-0x00E0F7E4 */
        (*event_count)++;
        APP_$RECEIVE((uint16_t)sock_num, &rec, &status);
        if (status != status_$ok) {
            continue;
        }

        /* 0x00E0F7E6-0x00E0F804 */
        reply = (const app_$reply_hdr_t *)ARCH_VA_TO_PTR(rec.reply);
        *data_len_out = reply->data_len;
        len = 0xB8;
        if (reply->template_len < len) {
            len = reply->template_len;
        }
        *resp_len_out = (int16_t)len;
        reply_id = reply->request_id;

        /* 0x00E0F808-0x00E0F812: the length is sign-extended (ext.l) */
        OS_$DATA_COPY(ARCH_VA_TO_PTR(rec.data), resp_buf,
                      (uint32_t)(int32_t)(int16_t)len);

        /* 0x00E0F81C-0x00E0F832: andi.w #-0x400 on the low word */
        hdr = rec.data & 0xFFFFFC00u;
        NETBUF_$RTN_HDR(&hdr);

        /* 0x00E0F834-0x00E0F840 */
        for (i = 0; i < 4; i++) {
            data_bufs[i] = rec.data_pages[i];
        }

        /* 0x00E0F842-0x00E0F844 */
        if (reply_id == pkt_id) {
            return result;
        }

        /* 0x00E0F846-0x00E0F85A */
        if (data_bufs[0] != 0) {
            PKT_$DUMP_DATA(data_bufs, (int16_t)*data_len_out);
        }
        data_bufs[0] = 0;
    }
}
